CREATE TABLE Log_Tamizaje
(
    ID_LOG INT IDENTITY(1,1) PRIMARY KEY,
    ID_TAMIZAJE INT NULL,
    Operacion VARCHAR(20) NOT NULL,
    FechaOperacion DATETIME NOT NULL DEFAULT GETDATE(),
    UsuarioSQL VARCHAR(100) NOT NULL DEFAULT SUSER_SNAME(),
    Descripcion VARCHAR(500) NULL
);
GO
CREATE OR ALTER PROCEDURE sp_InsertarTamizaje
(
    @ID_TAMIZAJE INT,
    @Anio INT,
    @NroMes INT,
    @ubigeo CHAR(6),
    @Departamento VARCHAR(50),
    @Provincia VARCHAR(50),
    @Distrito VARCHAR(50),
    @Sexo CHAR(1),
    @Etapa VARCHAR(20),
    @GrupoTamizaje VARCHAR(50),
    @DetalleTamizaje VARCHAR(100),
    @Casos INT
)
AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        -- Validar año
        IF @Anio < 2000 OR @Anio > 2100
        BEGIN
            THROW 50001, 'El año ingresado no es válido.', 1;
        END;

        -- Validar mes
        IF @NroMes < 1 OR @NroMes > 12
        BEGIN
            THROW 50002, 'El número de mes debe estar entre 1 y 12.', 1;
        END;

        -- Validar UBIGEO
        IF LEN(@ubigeo) <> 6
        BEGIN
            THROW 50003, 'El UBIGEO debe tener 6 caracteres.', 1;
        END;

        -- Validar sexo
        IF @Sexo NOT IN ('F', 'M')
        BEGIN
            THROW 50004, 'El sexo debe ser F o M.', 1;
        END;

        -- Validar casos
        IF @Casos < 0
        BEGIN
            THROW 50005, 'La cantidad de casos no puede ser negativa.', 1;
        END;

        -- Validar ID duplicado
        IF EXISTS
        (
            SELECT 1
            FROM Tamizaje
            WHERE ID_TAMIZAJE = @ID_TAMIZAJE
        )
        BEGIN
            THROW 50006, 'El ID_TAMIZAJE ya existe.', 1;
        END;

        -- Insertar en la tabla principal EXISTENTE
            ID_TAMIZAJE,
            Anio,
            NroMes,
            ubigeo,
            Departamento,
            Provincia,
            Distrito,
            Sexo,
            Etapa,
            GrupoTamizaje,
            DetalleTamizaje,
            Casos
        )
        VALUES
        (
            @ID_TAMIZAJE,
            @Anio,
            @NroMes,
            @ubigeo,
            @Departamento,
            @Provincia,
            @Distrito,
            @Sexo,
            @Etapa,
            @GrupoTamizaje,
            @DetalleTamizaje,
            @Casos
        );

        COMMIT TRANSACTION;

        PRINT 'Registro insertado correctamente.';

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        PRINT 'Error: ' + ERROR_MESSAGE();

    END CATCH

END;
GO

