CREATE OR ALTER PROCEDURE sp_ProcesarLoteTamizaje
AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        -- Crear punto de guardado
        SAVE TRANSACTION PuntoValidacion;

        -- Validar año
        IF EXISTS
        (
            SELECT 1
            FROM Staging_Tamizaje
            WHERE Anio < 2000 OR Anio > 2100
        )
        BEGIN
            ROLLBACK TRANSACTION PuntoValidacion;

            THROW 50010,
            'Existen registros con un año inválido.',
            1;
        END;

        -- Validar mes
        IF EXISTS
        (
            SELECT 1
            FROM Staging_Tamizaje
            WHERE NroMes < 1 OR NroMes > 12
        )
        BEGIN
            ROLLBACK TRANSACTION PuntoValidacion;

            THROW 50011,
            'Existen registros con un mes inválido.',
            1;
        END;

        -- Validar sexo
        IF EXISTS
        (
            SELECT 1
            FROM Staging_Tamizaje
            WHERE Sexo NOT IN ('F', 'M')
        )
        BEGIN
            ROLLBACK TRANSACTION PuntoValidacion;

            THROW 50012,
            'Existen registros con sexo inválido.',
            1;
        END;

        -- Validar casos
        IF EXISTS
        (
            SELECT 1
            FROM Staging_Tamizaje
            WHERE Casos < 0
        )
        BEGIN
            ROLLBACK TRANSACTION PuntoValidacion;

            THROW 50013,
            'Existen registros con casos negativos.',
            1;
        END;

        -- Validar UBIGEO
        IF EXISTS
        (
            SELECT 1
            FROM Staging_Tamizaje
            WHERE LEN(ubigeo) <> 6
        )
        BEGIN
            ROLLBACK TRANSACTION PuntoValidacion;

            THROW 50014,
            'Existen UBIGEO inválidos.',
            1;
        END;

        -- Insertar solamente IDs que todavía no existan
            ID_TAMIZAJE,
            Anio,
            NroMes,
            ubigeo,
            Departamento,
            Provincia,
            Distrito,
            Sexo,
            Etapa,
            GrupoTamizaje,
            DetalleTamizaje,
            Casos
        )
        SELECT
            S.ID_TAMIZAJE,
            S.Anio,
            S.NroMes,
            S.ubigeo,
            S.Departamento,
            S.Provincia,
            S.Distrito,
            S.Sexo,
            S.Etapa,
            S.GrupoTamizaje,
            S.DetalleTamizaje,
            S.Casos
        FROM Staging_Tamizaje S
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM Tamizaje T
            WHERE T.ID_TAMIZAJE = S.ID_TAMIZAJE
        );

        COMMIT TRANSACTION;

        PRINT 'Lote procesado correctamente.';

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        PRINT 'Error durante el procesamiento: '
              + ERROR_MESSAGE();

    END CATCH

END;
GO

CREATE OR ALTER TRIGGER trg_Tamizaje_Auditoria
ON dbo.Tamizaje
AFTER INSERT, UPDATE, DELETE
AS
BEGIN

    SET NOCOUNT ON;

    -- INSERT
        ID_TAMIZAJE,
        Operacion,
        Descripcion
    )
    SELECT
        I.ID_TAMIZAJE,
        'INSERT',
        'Se insertó un registro de tamizaje.'
    FROM inserted I
    LEFT JOIN deleted D
        ON I.ID_TAMIZAJE = D.ID_TAMIZAJE
    WHERE D.ID_TAMIZAJE IS NULL;


    -- UPDATE
        ID_TAMIZAJE,
        Operacion,
        Descripcion
    )
    SELECT
        I.ID_TAMIZAJE,
        'UPDATE',
        'Se modificó un registro de tamizaje.'
    FROM inserted I
    INNER JOIN deleted D
        ON I.ID_TAMIZAJE = D.ID_TAMIZAJE;


    -- DELETE
        ID_TAMIZAJE,
        Operacion,
        Descripcion
    )
    SELECT
        D.ID_TAMIZAJE,
        'DELETE',
        'Se eliminó un registro de tamizaje.'
    FROM deleted D
    LEFT JOIN inserted I
        ON D.ID_TAMIZAJE = I.ID_TAMIZAJE
    WHERE I.ID_TAMIZAJE IS NULL;

END;
GO


--Primer trigger de integridad
CREATE OR ALTER TRIGGER dbo.trg_Tamizaje_Auditoria
ON dbo.Tamizaje
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    -- INSERT
        ID_TAMIZAJE,
        Operacion,
        Descripcion
    )
    SELECT
        I.ID_TAMIZAJE,
        'INSERT',
        'Se insertó un registro de tamizaje.'
    FROM inserted AS I
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM deleted AS D
        WHERE D.ID_TAMIZAJE = I.ID_TAMIZAJE
    );


    -- UPDATE
        ID_TAMIZAJE,
        Operacion,
        Descripcion
    )
    SELECT
        I.ID_TAMIZAJE,
        'UPDATE',
        'Se modificó un registro de tamizaje.'
    FROM inserted AS I
    INNER JOIN deleted AS D
        ON I.ID_TAMIZAJE = D.ID_TAMIZAJE;


    -- DELETE
        ID_TAMIZAJE,
        Operacion,
        Descripcion
    )
    SELECT
        D.ID_TAMIZAJE,
        'DELETE',
        'Se eliminó un registro de tamizaje.'
    FROM deleted AS D
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM inserted AS I
        WHERE I.ID_TAMIZAJE = D.ID_TAMIZAJE
    );

END;
GO

--Segungo trigger
CREATE OR ALTER TRIGGER trg_Tamizaje_Integridad
ON Tamizaje
AFTER INSERT, UPDATE
AS
BEGIN

    SET NOCOUNT ON;

    -- Casos negativos
    IF EXISTS
    (
        SELECT 1
        FROM inserted
        WHERE Casos < 0
    )
    BEGIN
        THROW 50020,
        'Integridad: Casos no puede ser negativo.',
        1;
    END;

    -- Mes inválido
    IF EXISTS
    (
        SELECT 1
        FROM inserted
        WHERE NroMes < 1 OR NroMes > 12
    )
    BEGIN
        THROW 50021,
        'Integridad: NroMes debe estar entre 1 y 12.',
        1;
    END;

    -- Sexo inválido
    IF EXISTS
    (
        SELECT 1
        FROM inserted
        WHERE Sexo NOT IN ('F', 'M')
    )
    BEGIN
        THROW 50022,
        'Integridad: Sexo debe ser F o M.',
        1;
    END;

    -- UBIGEO inválido
    IF EXISTS
    (
        SELECT 1
        FROM inserted
        WHERE LEN(ubigeo) <> 6
    )
    BEGIN
        THROW 50023,
        'Integridad: UBIGEO debe tener 6 caracteres.',
        1;
    END;

END;
GO
--Creamos funcion
CREATE OR ALTER FUNCTION fn_ClasificarCasos
(
    @Casos INT
)
RETURNS VARCHAR(20)
AS
BEGIN

    DECLARE @Resultado VARCHAR(20);

    IF @Casos = 0
        SET @Resultado = 'SIN CASOS';

    ELSE IF @Casos BETWEEN 1 AND 10
        SET @Resultado = 'BAJO';

    ELSE IF @Casos BETWEEN 11 AND 50
        SET @Resultado = 'MEDIO';

    ELSE
        SET @Resultado = 'ALTO';

    RETURN @Resultado;

END;
GO

SELECT
    ID_TAMIZAJE,
    Anio,
    Departamento,
    Provincia,
    Distrito,
    Sexo,
    Etapa,
    DetalleTamizaje,
    Casos,
    dbo.fn_ClasificarCasos(Casos) AS Clasificacion
FROM dbo.Tamizaje;